      ro: "Un munte de importanță istorică și culturală la nord de orașul Tai'an. Unul dintre 'Cei Cinci Munți Sacri ai Chinei'.",
      en: "A mountain of historical and cultural significance located north of the city of Tai'an. One of the 'Five Great Mountains of China'.",
      es: "Una montaña de importancia histórica y cultural al norte de la ciudad de Tai'an. Una de las 'Cinco Montañas Sagradas de China'.",
      pt: "Uma montanha de importância histórica e cultural a norte da cidade de Tai'an. Uma das 'Cinco Montanhas Sagradas da China'.",
